import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, mix, vec3, sin, fract } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const colors = (config.intent && config.intent.visualSpec && config.intent.visualSpec.colors) || config.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new THREE.Group();
  root.name = 'journal-card-1-label';

  const content = new THREE.Group();
  root.add(content);

  // ---- card backing plane (engineered gradient + brushed metal + grain) ----
  const cardWidth = 1.3;
  const cardHeight = 0.46;
  const cardGeo = new THREE.PlaneGeometry(cardWidth, cardHeight);

  const placeholderTex = new THREE.Texture();
  const mapNode = texture(placeholderTex);

  const surfaceColor = new THREE.Color(colors.surface);
  const inkColor = new THREE.Color(colors.ink);

  const uvNode = uv();
  const gradientNode = mix(
    vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b),
    vec3(inkColor.r, inkColor.g, inkColor.b),
    uvNode.y
  );

  const grainSeed = uvNode.x.mul(12.9898).add(uvNode.y.mul(78.233));
  const grain = fract(sin(grainSeed).mul(43758.5453)).mul(0.035).sub(0.0175);

  const baseColor = mapNode.rgb.mul(gradientNode);
  const finalColor = baseColor.add(grain);

  const cardMat = new MeshPhysicalNodeMaterial({
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3,
    transparent: true,
    opacity: 0,
  });
  cardMat.colorNode = finalColor;

  const cardMesh = new THREE.Mesh(cardGeo, cardMat);
  cardMesh.position.set(0, 0, 0);
  content.add(cardMesh);

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.wrapS = THREE.RepeatWrapping;
    tex.wrapT = THREE.RepeatWrapping;
    mapNode.value = tex;
  }).catch(() => {
    // texture missing — gradient + grain still carry the surface
  });

  // ---- rim / accent light, node-local only ----
  const accentColor = new THREE.Color(colors.accent);
  const rimLight = new THREE.DirectionalLight(accentColor, 0.6);
  rimLight.position.set(0.6, 0.5, 0.8);
  const rimTarget = new THREE.Object3D();
  rimTarget.position.set(0, 0, 0);
  content.add(rimLight);
  content.add(rimTarget);
  rimLight.target = rimTarget;

  // ---- headline text ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [
    { text: 'Journal 1', role: 'headline', typography: { fontSize: 39 } },
  ];
  const headlineItem = items.find((i) => i.role === 'headline') ?? items[0];
  const fontSize = (headlineItem && headlineItem.typography && headlineItem.typography.fontSize) || 39;

  const textObj = ctx.fontAtlas.createText(headlineItem ? headlineItem.text : 'Journal 1', {
    fontSize,
    color: colors.paper,
    align: 'left',
  });
  textObj.position.set(-cardWidth / 2 + 0.12, 0.03, 0.03);
  content.add(textObj);

  // ---- accent underline strip (<=10% of frame, single accent use) ----
  const underlineGeo = new THREE.PlaneGeometry(0.55, 0.018);
  const underlineMat = new MeshBasicNodeMaterial({
    color: accentColor,
    transparent: true,
    opacity: 0,
  });
  const underline = new THREE.Mesh(underlineGeo, underlineMat);
  underline.position.set(-cardWidth / 2 + 0.12 + 0.275, -0.12, 0.03);
  content.add(underline);

  // ---- collect transparent materials for fade-up entrance ----
  const fadeMaterials = [cardMat, underlineMat];
  content.traverse((obj) => {
    if (obj.material && obj !== cardMesh && obj !== underline) {
      const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
      mats.forEach((m) => {
        if (m && 'opacity' in m) {
          m.transparent = true;
          fadeMaterials.push(m);
        }
      });
    }
  });

  // ---- weighted entrance: fade-up, power2.out ----
  content.position.y -= 0.2;
  fadeMaterials.forEach((m) => { m.opacity = 0; });

  const tl = gsap.timeline();
  tl.to(content.position, {
    y: '+=0.2',
    duration: 0.6,
    ease: 'power2.out',
  }, 0);
  fadeMaterials.forEach((m) => {
    tl.to(m, {
      opacity: 1,
      duration: 0.5,
      ease: 'power2.out',
      onUpdate: () => { m.needsUpdate = true; },
    }, 0);
  });

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();

    cardGeo.dispose();
    cardMat.dispose();
    underlineGeo.dispose();
    underlineMat.dispose();

    if (placeholderTex) placeholderTex.dispose();
    if (mapNode.value && mapNode.value.isTexture) mapNode.value.dispose();

    content.remove(rimLight);
    content.remove(rimTarget);
    rimLight.dispose && rimLight.dispose();

    content.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
        mats.forEach((m) => m && m.dispose && m.dispose());
      }
    });
  };

  return root;
}
